{{ get_solua_print_css() }}{% set p = get_wholesale_print_data(doc) %}{% set company = p.company %}{% set customer = p.customer %}{% set show_item_name = doc.get('custom_print_item_name') if doc.get('custom_print_item_name') is not none else 1 %}{% set show_sku = doc.get('custom_print_sku') if doc.get('custom_print_sku') is not none else 1 %}{% set show_color_code = doc.get('custom_print_color_code') if doc.get('custom_print_color_code') is not none else 1 %}{% set show_description = doc.get('custom_print_description') if doc.get('custom_print_description') is not none else 1 %}{% set show_images = 1 %}
<div class="company-header">{% if company.logo %}<img class="company-logo" src="{{ company.logo | e }}" alt="Solua Home">{% endif %}<h2>Confirmação de Encomenda / 订单确认单</h2></div>
{% if doc.docstatus != 1 %}<div class="warning">{{ 'RASCUNHO / 草稿' if doc.docstatus == 0 else 'CANCELADO / 已取消' }} — 非正式凭证</div>{% endif %}
{% if p.get('legacy') %}<div class="warning">历史单据未保存打印快照，所示补充主资料为当前资料。</div>{% endif %}
<table class="meta"><tr><td><b>{{ company.name | e }}</b><br>NUIT: {{ company.nuit | e }}<br>{{ company.address }}<br>Tel: {{ company.phone | e }}</td><td><b>Cliente / 客户: {{ customer.name | e }}</b><br>NUIT: {{ customer.nuit or 'Não informado / 未提供' | e }}<br>Loja / 门店: {{ customer.store | e }}<br>{{ customer.address }}<br>{{ customer.contact }} · {{ customer.phone | e }}</td></tr><tr><td>N.º / 编号: {{ doc.name | e }}<br>客户订单号: {{ doc.get('custom_customer_order_no') or '—' | e }}</td><td>Data / 日期: {{ doc.get('posting_date') or doc.get('transaction_date') }}<br>交期: {{ doc.get('delivery_date') or '—' }}</td></tr></table>
<table class="items"><colgroup><col data-col="image" class="col-photo">{% if show_item_name %}<col data-col="name" class="col-item">{% endif %}{% if show_sku %}<col data-col="sku" class="col-sku">{% endif %}{% if show_color_code %}<col data-col="cor" class="col-color-code">{% endif %}<col data-col="barcode" class="col-barcode">{% if show_description %}<col data-col="description" class="col-description">{% endif %}<col data-col="qty" class="col-qty"><col data-col="uom" class="col-uom"><col data-col="rate" class="col-rate"><col data-col="amount" class="col-amount"></colgroup><caption class="items-title">{{ doc.name | e }} · Encomenda / 订购</caption><thead><tr>{% if show_images %}<th class="col-photo">Imagem / 图片</th>{% endif %}{% if show_item_name %}<th class="col-item">Artigo / 商品</th>{% endif %}{% if show_sku %}<th class="col-sku">SKU / 货号</th>{% endif %}{% if show_color_code %}<th class="col-color-code">Cor /<br>色号</th>{% endif %}<th class="col-barcode">EAN /<br>条码</th>{% if show_description %}<th class="col-description">Descrição /<br>描述</th>{% endif %}<th class="col-qty"><span class="nowrap">Qtd. /</span><br>数量</th><th class="col-uom">Un.</th><th class="col-rate">Preço /<br>单价</th><th class="col-amount">Valor /<br>金额</th></tr></thead><tbody>
{% for item in p['items'] %}<tr>{% if show_images %}<td class="col-photo">{% if item.image %}<img class="photo" src="{{ item.image | e }}">{% endif %}</td>{% endif %}{% if show_item_name %}<td class="col-item">{{ item.item_name | e }}</td>{% endif %}{% if show_sku %}<td class="col-sku">{{ (item.order_code or item.item_code) | e }}{% if item.order_code and item.item_code and item.order_code != item.item_code %}<br><small>{{ item.item_code | e }}</small>{% endif %}</td>{% endif %}{% if show_color_code %}<td class="col-color-code">{{ (item.color_code or '—') | e }}{% if item.color %}<br>{{ item.color | e }}{% endif %}</td>{% endif %}<td class="col-barcode">{{ (item.get('barcode') or '—') | e }}</td>{% if show_description %}<td class="col-description">{{ (item.get('description') or '—') | e }}</td>{% endif %}<td class='col-qty num'>{{ format_print_qty(item.qty) }}</td><td class="col-uom">{{ item.uom | e }}</td><td class="col-rate num">{{ format_print_money(item.rate, precision=0) }}</td><td class="col-amount num">{{ format_print_money(item.amount, precision=0) }}</td></tr>{% endfor %}
</tbody><tbody class="items-total"><tr><td colspan='{{ 1 + show_images + show_item_name + show_sku + show_color_code + show_description }}' style='text-align:right'><b>Total Qty /<br>总数量</b></td><td style='text-align:right'><b>{{ get_print_total_qty(p) }}</b></td><td colspan='3'></td></tr></tbody></table><div class="block num">Total / 含税合计: {{ format_print_money(doc.grand_total, currency=doc.currency, precision=0) }} {{ doc.currency | e }}</div>
<div class="block">付款安排: {{ p.payment_method or '未维护' | e }} · 定金: {{ format_print_money(p.deposit, precision=0) }} · 尾款到期: {{ p.balance_due_date or '—' | e }}<br>开票安排: {{ p.invoice_plan or '未维护' | e }}</div>
{% if doc.get('payment_schedule') %}<table><thead><tr><th>付款条件</th><th>到期日</th><th>金额</th></tr></thead><tbody>{% for row in doc.payment_schedule %}<tr><td>{{ row.payment_term or '' | e }}</td><td>{{ row.due_date }}</td><td>{{ format_print_money(row.payment_amount, precision=0) }}</td></tr>{% endfor %}</tbody></table>{% endif %}
{% if doc.get('custom_print_color_qr') %}{% set seen = [] %}<div class="block">{% for item in p['items'] %}{% if item.template_code and item.template_code not in seen %}{% set unused = seen.append(item.template_code) %}{% set qr = get_color_card_qr_img(item.template_code) %}{% if qr %}<img class="qr" src="{{ qr | e }}">{{ item.template_code | e }} {% endif %}{% endif %}{% endfor %}</div>{% endif %}
<div id="footer-html" class="visible-pdf"><div class="text-center">{{ doc.name | e }} · <span class="page"></span> / <span class="topage"></span></div></div>

css:
@page{size:A4;margin:0}
.print-format{width:210mm;min-height:297mm;margin:0 auto;padding:12mm;box-sizing:border-box;color:#25313a;font-size:9pt;line-height:1.35;overflow-wrap:anywhere}
.print-format h1,.print-format h2,.print-format h3{line-height:1.15}
.print-format .company-header h2{font-size:18pt;color:#99732c}
.print-format .items{width:100%;table-layout:fixed;border-collapse:collapse;font-size:9pt;line-height:1.35}









.print-format .items col[data-col="image"]{width:6.542%;min-width:0}
.print-format .items col[data-col="name"]{width:13.699%;min-width:0}
.print-format .items col[data-col="sku"]{width:13.699%;min-width:0}
.print-format .items col[data-col="cor"]{width:5.536%;min-width:0}
.print-format .items col[data-col="barcode"]{width:13.832%;min-width:0}
.print-format .items col[data-col="description"]{width:18.967%;min-width:0}
.print-format .items col[data-col="qty"]{width:5.596%;min-width:0}
.print-format .items col[data-col="uom"]{width:6.322%;min-width:0}
.print-format .items col[data-col="rate"]{width:7.376%;min-width:0}
.print-format .items col[data-col="amount"]{width:8.430%;min-width:0}
.print-format .items th{font-size:9pt;background:#f5f1e9}
.print-format .items th,.print-format .items td{padding:1.5mm;border:1px solid #aeb8be;vertical-align:top;overflow-wrap:anywhere;word-break:normal}
.print-format .items thead{display:table-header-group!important}
.print-format .items tr{break-inside:avoid;page-break-inside:avoid}
.print-format .items tbody td{font-size:9pt}
.print-format .items-title{caption-side:top;background:#f5f1e9;border:1px solid #aeb8be;padding:1.5mm;text-align:left}
.print-format .meta td{width:50%;border:1px solid #aeb8be;padding:1.5mm;vertical-align:top}
.print-format .warning{color:#a35c00}
.print-format .num{text-align:right;white-space:nowrap}
.print-format .block{page-break-inside:avoid;margin-top:7px}
.print-format .qr{height:60px;width:60px}

.print-format .items .photo{display:block;max-width:100%;max-height:20mm;width:auto;height:auto;object-fit:contain}
